def build_candidate_index(candidates: Sequence[Candidate]) -> dict[str, Candidate]:
    """``candidate_id`` → candidate, refusing duplicates.

    Small, but it is the lookup every caller of the two builders needs,
    and writing it inline invites a dict comprehension that silently
    keeps the last of two identical ids.
    """
    index: dict[str, Candidate] = {}
    for candidate in candidates:
        if candidate.candidate_id in index:
            raise CardError(
                f"candidate {candidate.candidate_id} appears twice; the same configuration "
                "cannot hold two rows on one card"
            )
        index[candidate.candidate_id] = candidate
    return index

